/* ---------------- geometry ---------------- */
function buildCoin(seg,reeds,amp){
  var R=1,H=.075,rings=[0,.16,.30,.43,.55,.66,.75,.83,.895,.94,.972,1.0];
  var pos=[],nrm=[],uvs=[],fac=[],idx=[],i,s,side;
  function rp(t){return R+amp*Math.cos(reeds*t);}
  function drp(t){return -amp*reeds*Math.sin(reeds*t);}
  function zA(r){if(r<=.94)return H;var u=(r-.94)/.06;return H*(1-.45*u*u);}
  function dz(r){if(r<=.94)return 0;var u=(r-.94)/.06;return H*(-.9*u)/.06;}
  for(var si=0;si<2;si++){
    side=si===0?1:-1;
    var start=pos.length/3;
    for(i=0;i<rings.length;i++){
      var rr=rings[i],sl=dz(rr);
      for(s=0;s<=seg;s++){
        var th=s/seg*6.283185307,ct=Math.cos(th),st=Math.sin(th);
        var rad=(i===rings.length-1)?rp(th):rr*R;
        var px=rad*ct,py=rad*st;
        pos.push(px,py,side*zA(rr));
        var nx=-sl*ct,ny=-sl*st,nz=side,L=Math.sqrt(nx*nx+ny*ny+nz*nz);
        nrm.push(nx/L,ny/L,nz/L);
        uvs.push(.5+side*.5*px/R, .5-.5*py/R);
        fac.push(side);
      }
    }
    for(i=0;i<rings.length-1;i++)for(s=0;s<seg;s++){
      var a=start+i*(seg+1)+s,b=a+1,c2=a+seg+1,d=c2+1;
      idx.push(a,c2,b, b,c2,d);
    }
  }
  var rows=[[.55,1,.86],[.22,1.006,.14],[-.22,1.006,-.14],[-.55,1,-.86]];
  var estart=pos.length/3;
  for(i=0;i<rows.length;i++){
    for(s=0;s<=seg;s++){
      var th2=s/seg*6.283185307,ct2=Math.cos(th2),st2=Math.sin(th2);
      var r0=rp(th2),d0=drp(th2),rad2=r0*rows[i][1];
      pos.push(rad2*ct2,rad2*st2,rows[i][0]*H*(1/.55)*.55);
      var ex=r0*ct2+d0*st2, ey=r0*st2-d0*ct2, ez=rows[i][2];
      var L2=Math.sqrt(ex*ex+ey*ey+ez*ez);
      nrm.push(ex/L2,ey/L2,ez/L2);
      uvs.push(0,0);fac.push(0);
    }
  }
  for(i=0;i<rows.length-1;i++)for(s=0;s<seg;s++){
    var a2=estart+i*(seg+1)+s,b2=a2+1,c3=a2+seg+1,d2=c3+1;
    idx.push(a2,c3,b2, b2,c3,d2);
  }
  return {pos:new Float32Array(pos),nrm:new Float32Array(nrm),uv:new Float32Array(uvs),
          fac:new Float32Array(fac),idx:new Uint16Array(idx)};
}

