  var bi=buf(g.idx,gl.ELEMENT_ARRAY_BUFFER),count=g.idx.length;
  var quad=buf(new Float32Array([-1,-1,3,-1,-1,3]),AB);

  var S=o.texSize;
  var tf=tex(gl,makeFront(S,o.front)),tb=tex(gl,makeBack(S,o.back));

  var A={p:gl.getAttribLocation(P,"aP"),n:gl.getAttribLocation(P,"aN"),
         u:gl.getAttribLocation(P,"aU"),f:gl.getAttribLocation(P,"aF")};
  var U={proj:gl.getUniformLocation(P,"uProj"),mv:gl.getUniformLocation(P,"uMV"),
         nm:gl.getUniformLocation(P,"uNM"),tf:gl.getUniformLocation(P,"uTF"),
         tb:gl.getUniformLocation(P,"uTB"),base:gl.getUniformLocation(P,"uBase"),
         texel:gl.getUniformLocation(P,"uTexel"),rel:gl.getUniformLocation(P,"uRelief"),
         irid:gl.getUniformLocation(P,"uIrid"),pol:gl.getUniformLocation(P,"uPolish")};
  var BA=gl.getAttribLocation(BP,"aP");
  gl.enable(gl.DEPTH_TEST);gl.disable(gl.CULL_FACE);

  var W=1,Hh=1;
