    var dpr=Math.min(window.devicePixelRatio||1,2);
    var cw=canvas.clientWidth||canvas.width, chh=canvas.clientHeight||canvas.height;
    var w=Math.max(2,Math.round(cw*dpr)),h=Math.max(2,Math.round(chh*dpr));
    if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
