    var model=mul(rZ(o.roll||0),mul(rX(pitch),rY(yaw)));
    var mv=mul(tr(0,0,-o.dist),model);
    var pr=persp(o.fov,W/Hh,0.1,60);

    gl.useProgram(P);
    function bind(b,loc,size){gl.bindBuffer(AB,b);gl.enableVertexAttribArray(loc);
      gl.vertexAttribPointer(loc,size,gl.FLOAT,false,0,0);}
    bind(bp,A.p,3);bind(bn,A.n,3);bind(bu,A.u,2);bind(bf,A.f,1);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,bi);
    gl.uniformMatrix4fv(U.proj,false,pr);
    gl.uniformMatrix4fv(U.mv,false,mv);
    gl.uniformMatrix3fv(U.nm,false,m3(model));
    gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,tf);gl.uniform1i(U.tf,0);
    gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,tb);gl.uniform1i(U.tb,1);
    gl.uniform3fv(U.base,o.base);
    gl.uniform1f(U.texel,1.4/S);
    gl.uniform1f(U.rel,o.relief||2.0);
    gl.uniform1f(U.irid,o.irid||0);
    gl.uniform1f(U.pol,o.polish||1);
