}

/* ---------------- 2D fallback (orthographic coin) ---------------- */
function makeFallback(canvas,o){
  var x=canvas.getContext("2d");
  var S=o.texSize>512?512:o.texSize;
  var fc=makeFront(S,o.front),bc=makeBack(S,o.back);
  var col=o.base;
  function hex(v){var c=Math.max(0,Math.min(255,Math.round(v*255)));return c;}
  function rgb(m){return "rgb("+hex(col[0]*m)+","+hex(col[1]*m)+","+hex(col[2]*m)+")";}
  function resize(){
    var dpr=Math.min(window.devicePixelRatio||1,2);
    var w=Math.max(2,Math.round((canvas.clientWidth||canvas.width)*dpr));
    var h=Math.max(2,Math.round((canvas.clientHeight||canvas.height)*dpr));
    if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
  }
  function render(t){
    resize();
    var W=canvas.width,H=canvas.height,R=Math.min(W,H)*0.34;
    var g=x.createRadialGradient(W/2,H*0.45,0,W/2,H/2,Math.max(W,H)*0.7);
    g.addColorStop(0,"#12141b");g.addColorStop(1,"#050609");
    x.setTransform(1,0,0,1,0,0);x.fillStyle=g;x.fillRect(0,0,W,H);
    var tt=t-Math.floor(t),yaw=o.yaw(tt),pitch=o.pitch(tt);
    // face normal after Rx(pitch)*Ry(yaw) applied to (0,0,1)
    var nz=Math.cos(pitch)*Math.cos(yaw), ny=-Math.sin(pitch)*Math.cos(yaw), nx=Math.sin(yaw);
    var ux=Math.cos(yaw), uy=0, uz=-Math.sin(yaw);              // local X axis
    var vx=Math.sin(pitch)*Math.sin(yaw), vy=Math.cos(pitch), vz=Math.sin(pitch)*Math.cos(yaw); // local Y
    var th=R*0.09;
    var front=nz>=0, img=front?fc:bc;
    x.save();x.translate(W/2,H/2);
    // edge band: offset silhouette
    var ex=nx*th, ey=-ny*th;
    x.save();
    x.beginPath();
    var i,N2=90;
    for(i=0;i<=N2;i++){var a=i/N2*6.2832;
      x.lineTo(R*(ux*Math.cos(a)+vx*Math.sin(a))+ex, -R*(uy*Math.cos(a)+vy*Math.sin(a))+ey);}
    for(i=N2;i>=0;i--){var a2=i/N2*6.2832;
      x.lineTo(R*(ux*Math.cos(a2)+vx*Math.sin(a2))-ex, -R*(uy*Math.cos(a2)+vy*Math.sin(a2))-ey);}
    var lg=x.createLinearGradient(-R,-R,R,R);
    lg.addColorStop(0,rgb(.25));lg.addColorStop(.45,rgb(1.15));lg.addColorStop(.6,rgb(.55));lg.addColorStop(1,rgb(.2));
    x.fillStyle=lg;x.fill();
    x.strokeStyle=rgb(.35);x.lineWidth=Math.max(1,R*0.008);
    for(i=0;i<120;i++){var a3=i/120*6.2832;
      var px=R*(ux*Math.cos(a3)+vx*Math.sin(a3)),py=-R*(uy*Math.cos(a3)+vy*Math.sin(a3));
      x.beginPath();x.moveTo(px+ex,py+ey);x.lineTo(px-ex,py-ey);x.stroke();}
    x.restore();
    // face
    var sgn=front?1:-1;
    x.save();
    x.transform(R*ux*sgn, -R*uy*sgn, R*vx, -R*vy, nx*th*sgn, -ny*th*sgn);
    x.beginPath();x.arc(0,0,1,0,6.2832);x.clip();
    x.globalCompositeOperation="source-over";
    x.drawImage(img,-1,-1,2,2);
    x.restore();
    // metal tint + moving specular over the face
    x.save();
    x.transform(R*ux*sgn,-R*uy*sgn,R*vx,-R*vy,nx*th*sgn,-ny*th*sgn);
    x.beginPath();x.arc(0,0,1,0,6.2832);x.clip();
    x.globalCompositeOperation="multiply";x.fillStyle=rgb(1.0);x.fillRect(-1,-1,2,2);
    x.globalCompositeOperation="lighter";
    var sx=Math.cos(yaw*2.0),sy=Math.sin(pitch*2.0);
    var sg2=x.createLinearGradient(-1+sx,-1+sy,1+sx,1+sy);
    sg2.addColorStop(0,"rgba(255,255,255,0)");
    sg2.addColorStop(.44,"rgba(255,250,235,.55)");
    sg2.addColorStop(.52,"rgba(255,255,255,.75)");
    sg2.addColorStop(.62,"rgba(255,240,210,.18)");
    sg2.addColorStop(1,"rgba(255,255,255,0)");
    x.fillStyle=sg2;x.fillRect(-1,-1,2,2);
    x.restore();
    x.restore();
  }
  return {render:render,resize:resize};
}

