var PERIOD=9000, running=true, raf=0, t0=null;
function frame(now){
  if(!running)return;
  if(t0===null)t0=now;
  var t=((now-t0)/PERIOD)%1;
  hero.render(t);
  for(var i=0;i<tiles.length;i++){
    var e=tiles[i].el.getBoundingClientRect();
    if(e.bottom>-80&&e.top<window.innerHeight+80){
      tiles[i].r.render(((now-t0)/(PERIOD*1.8))*tiles[i].speed+tiles[i].phase);
    }
  }
  raf=requestAnimationFrame(frame);
}
